```typescript
import { select, input } from '@inquirer/prompts'
import type { Config, ConfigManager } from './config.js'
import { validateBotToken, validateChatId } from './setup.js'
import { installAutoStart, uninstallAutoStart, isAutoStartInstalled, isAutoStartSupported } from './autostart.js'
import { expandHome } from './config.js'

// ANSI color helpers
const c = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
}

const ok = (msg: string) => `${c.green}${c.bold}✓${c.reset} ${c.green}${msg}${c.reset}`
const dim = (msg: string) => `${c.dim}${msg}${c.reset}`
const header = (title: string) => `\n${c.cyan}${c.bold}[${title}]${c.reset}\n`

type ConfigUpdates = Record<string, unknown>
```

Then implement these functions (all take `config: Config` and `updates: ConfigUpdates`):

- `editTelegram` — Shows current botToken (truncated) and chatId. Menu: Change Bot Token, Change Chat ID, Back. Validates token via `validateBotToken`, chatId via `validateChatId`. Saves even if validation fails (with warning). Uses nested record updates: `updates.channels.telegram.botToken`.

- `editAgent` — Shows current agents and default. Menu: Change default agent, Back.

- `editWorkspace` — Shows current baseDir. Input prompt with current as default.

- `editSecurity` — Shows allowedUserIds, maxConcurrentSessions, sessionTimeoutMinutes. Menu: Max concurrent sessions, Session timeout, Back.

- `editLogging` — Shows level and logDir. Menu: Log level (select from enum), Log directory (input), Back.

- `editRunMode` — Shows current mode and autoStart status. Menu: Switch to daemon/foreground, Toggle auto-start, Back. When switching to daemon: sets `runMode: 'daemon'`, installs autostart. When switching to foreground: sets `runMode: 'foreground'`, `autoStart: false`, uninstalls autostart. Toggle auto-start works independently.

- `runConfigEditor(configManager)` — Main loop. Loads config. Shows main menu (Telegram, Agent, Workspace, Security, Logging, Run Mode, Exit). Dispatches to edit functions. On Exit: saves accumulated updates via `configManager.save(updates)`. On Ctrl+C (ExitPromptError): discards changes.

IMPORTANT: All nested update objects must be built carefully with type assertions since `ConfigUpdates` is `Record<string, unknown>`. Follow this pattern for nested updates:
```typescript
if (!updates.channels) updates.channels = {}
if (!(updates.channels as Record<string, unknown>).telegram) (updates.channels as Record<string, unknown>).telegram = {}
;((updates.channels as Record<string, unknown>).telegram as Record<string, unknown>).botToken = token.trim()
```

The full implementation code for all these functions is provided in the plan — implement them exactly as specified.

