  1→import type { Bot, Context } from "grammy";
  2→import { InlineKeyboard } from "grammy";
  3→import type { OpenACPCore } from "../../core/index.js";
  4→import { escapeHtml } from "./formatting.js";
  5→import { createSessionTopic } from "./topics.js";
  6→import { createChildLogger } from '../../core/log.js'
  7→import { nanoid } from 'nanoid'
  8→import type { AgentCommand } from '../../core/index.js'
  9→const log = createChildLogger({ module: 'telegram-commands' })
 10→
 11→export function setupCommands(
 12→  bot: Bot,
 13→  core: OpenACPCore,
 14→  chatId: number,
 15→): void {
 16→  bot.command("new", (ctx) => handleNew(ctx, core, chatId));
 17→  bot.command("new_chat", (ctx) => handleNewChat(ctx, core, chatId));
 18→  bot.command("cancel", (ctx) => handleCancel(ctx, core));
 19→  bot.command("status", (ctx) => handleStatus(ctx, core));
 20→  bot.command("agents", (ctx) => handleAgents(ctx, core));
 21→  bot.command("help", (ctx) => handleHelp(ctx));
 22→  bot.command("menu", (ctx) => handleMenu(ctx));
 23→}
 24→
 25→export function buildMenuKeyboard(): InlineKeyboard {
 26→  return new InlineKeyboard()
 27→    .text("🆕 New Session", "m:new")
 28→    .text("💬 New Chat", "m:new_chat")
 29→    .row()
 30→    .text("⛔ Cancel", "m:cancel")
 31→    .text("📊 Status", "m:status")
 32→    .row()
 33→    .text("🤖 Agents", "m:agents")
 34→    .text("❓ Help", "m:help");
 35→}
 36→
 37→export function setupMenuCallbacks(
 38→  bot: Bot,
 39→  core: OpenACPCore,
 40→  chatId: number,
 41→): void {
 42→  bot.callbackQuery(/^m:/, async (ctx) => {
 43→    const data = ctx.callbackQuery.data;
 44→    try {
 45→      await ctx.answerCallbackQuery();
 46→    } catch {
 47→      /* expired or network — ignore */
 48→    }
 49→
 50→    switch (data) {
 51→      case "m:new":
 52→        await handleNew(ctx, core, chatId);
 53→        break;
 54→      case "m:new_chat":
 55→        await handleNewChat(ctx, core, chatId);
 56→        break;
 57→      case "m:cancel":
 58→        await handleCancel(ctx, core);
 59→        break;
 60→      case "m:status":
 61→        await handleStatus(ctx, core);
 62→        break;
 63→      case "m:agents":
 64→        await handleAgents(ctx, core);
 65→        break;
 66→      case "m:help":
 67→        await handleHelp(ctx);
 68→        break;
 69→    }
 70→  });
 71→}
 72→
 73→async function handleMenu(ctx: Context): Promise<void> {
 74→  await ctx.reply(`<b>OpenACP Menu</b>\nChoose an action:`, {
 75→    parse_mode: "HTML",
 76→    reply_markup: buildMenuKeyboard(),
 77→  });
 78→}
 79→
 80→async function handleNew(
 81→  ctx: Context,
 82→  core: OpenACPCore,
 83→  chatId: number,
 84→): Promise<void> {
 85→  const rawMatch = (ctx as Context & { match: unknown }).match;
 86→  const matchStr = typeof rawMatch === "string" ? rawMatch : "";
 87→  const args = matchStr.split(" ").filter(Boolean);
 88→  const agentName = args[0];
 89→  const workspace = args[1];
 90→
 91→  log.info({ userId: ctx.from?.id, agentName }, 'New session command')
 92→
 93→  // Create topic first so threadId is ready before session events fire
 94→  let threadId: number | undefined;
 95→  try {
 96→    const topicName = `🔄 New Session`;
 97→    threadId = await createSessionTopic(botFromCtx(ctx), chatId, topicName);
 98→
 99→    // Let user know we're setting up (spawn + warm-up can take a while)
100→    await ctx.api.sendMessage(chatId, `⏳ Setting up session, please wait...`, {
101→      message_thread_id: threadId,
102→      parse_mode: "HTML",
103→    });
104→
105→    const session = await core.handleNewSession(
106→      "telegram",
107→      agentName,
108→      workspace,
109→    );
110→    session.threadId = String(threadId);
111→
112→    // Rename topic with actual agent name
113→    const finalName = `🔄 ${session.agentName} — New Session`;
114→    try {
115→      await ctx.api.editForumTopic(chatId, threadId, { name: finalName });
116→    } catch {
117→      /* ignore rename failures */
118→    }
119→
120→    await ctx.api.sendMessage(
121→      chatId,
122→      `✅ Session started\n` +
123→        `<b>Agent:</b> ${escapeHtml(session.agentName)}\n` +
124→        `<b>Workspace:</b> <code>${escapeHtml(session.workingDirectory)}</code>`,
125→      {
126→        message_thread_id: threadId,
127→        parse_mode: "HTML",
128→      },
129→    );
130→
131→    // Warm up model cache in background while user types
132→    session.warmup().catch((err) => log.error({ err }, "Warm-up error"));
133→  } catch (err) {
134→    // Clean up orphaned topic if session creation failed
135→    if (threadId) {
136→      try {
137→        await ctx.api.deleteForumTopic(chatId, threadId);
138→      } catch {
139→        /* ignore cleanup failures */
140→      }
141→    }
142→    const message = err instanceof Error ? err.message : String(err);
143→    await ctx.reply(`❌ ${escapeHtml(message)}`, { parse_mode: "HTML" });
144→  }
145→}
146→
147→async function handleNewChat(
148→  ctx: Context,
149→  core: OpenACPCore,
150→  chatId: number,
151→): Promise<void> {
152→  const threadId = ctx.message?.message_thread_id;
153→  if (!threadId) {
154→    await ctx.reply(
155→      "Use /new_chat inside a session topic to inherit its config.",
156→      { parse_mode: "HTML" },
157→    );
158→    return;
159→  }
160→
161→  try {
162→    const session = await core.handleNewChat("telegram", String(threadId));
163→    if (!session) {
164→      await ctx.reply("No active session in this topic.", {
165→        parse_mode: "HTML",
166→      });
167→      return;
168→    }
169→
170→    const topicName = `🔄 ${session.agentName} — New Chat`;
171→    const newThreadId = await createSessionTopic(
172→      botFromCtx(ctx),
173→      chatId,
174→      topicName,
175→    );
176→
177→    await ctx.api.sendMessage(chatId, `⏳ Setting up session, please wait...`, {
178→      message_thread_id: newThreadId,
179→      parse_mode: "HTML",
180→    });
181→
182→    session.threadId = String(newThreadId);
183→
184→    await ctx.api.sendMessage(
185→      chatId,
186→      `✅ New chat (same agent &amp; workspace)\n` +
187→        `<b>Agent:</b> ${escapeHtml(session.agentName)}\n` +
188→        `<b>Workspace:</b> <code>${escapeHtml(session.workingDirectory)}</code>`,
189→      {
190→        message_thread_id: newThreadId,
191→        parse_mode: "HTML",
192→      },
193→    );
194→
195→    // Warm up model cache in background while user types
196→    session.warmup().catch((err) => log.error({ err }, "Warm-up error"));
197→  } catch (err) {
198→    const message = err instanceof Error ? err.message : String(err);
199→    await ctx.reply(`❌ ${escapeHtml(message)}`, { parse_mode: "HTML" });
200→  }
201→}
