218→async function handleStatus(ctx: Context, core: OpenACPCore): Promise<void> {
219→  const threadId = ctx.message?.message_thread_id;
220→  if (threadId) {
221→    const session = core.sessionManager.getSessionByThread(
222→      "telegram",
223→      String(threadId),
224→    );
225→    if (session) {
226→      await ctx.reply(
227→        `<b>Session:</b> ${escapeHtml(session.name || session.id)}\n` +
228→          `<b>Agent:</b> ${escapeHtml(session.agentName)}\n` +
229→          `<b>Status:</b> ${escapeHtml(session.status)}\n` +
230→          `<b>Workspace:</b> <code>${escapeHtml(session.workingDirectory)}</code>\n` +
231→          `<b>Queue:</b> ${session.promptQueue.length} pending`,
232→        { parse_mode: "HTML" },
233→      );
234→    } else {
235→      await ctx.reply("No active session in this topic.", {
236→        parse_mode: "HTML",
237→      });
238→    }
239→  } else {
240→    const sessions = core.sessionManager.listSessions("telegram");
241→    const active = sessions.filter(
242→      (s) => s.status === "active" || s.status === "initializing",
243→    );
244→    await ctx.reply(
245→      `<b>OpenACP Status</b>\n` +
246→        `Active sessions: ${active.length}\n` +
247→        `Total sessions: ${sessions.length}`,
248→      { parse_mode: "HTML" },
249→    );
250→  }
251→}
