268→async function handleHelp(ctx: Context): Promise<void> {
269→  await ctx.reply(
270→    `<b>OpenACP Commands:</b>\n\n` +
271→      `/new [agent] [workspace] — Create new session\n` +
272→      `/new_chat — New chat, same agent &amp; workspace\n` +
273→      `/cancel — Cancel current session\n` +
274→      `/status — Show session/system status\n` +
275→      `/agents — List available agents\n` +
276→      `/menu — Show interactive menu\n` +
277→      `/help — Show this help\n\n` +
278→      `Or just chat in the 🤖 Assistant topic for help!`,
