 77→export class ConfigManager {
 78→  private config!: Config
 79→  private configPath: string
 80→
 81→  constructor() {
 82→    this.configPath = process.env.OPENACP_CONFIG_PATH || expandHome('~/.openacp/config.json')
 83→  }
 84→
 85→  async load(): Promise<void> {
 86→    // 1. Ensure directory exists
 87→    const dir = path.dirname(this.configPath)
 88→    fs.mkdirSync(dir, { recursive: true })
 89→
 90→    // 2. If config file doesn't exist, create default
 91→    if (!fs.existsSync(this.configPath)) {
 92→      fs.writeFileSync(this.configPath, JSON.stringify(DEFAULT_CONFIG, null, 2))
 93→      log.info({ configPath: this.configPath }, 'Config created')
 94→      log.info('Please edit it with your Telegram bot token and chat ID, then restart.')
 95→      process.exit(1)
 96→    }
 97→
 98→    // 3. Read and parse
 99→    const raw = JSON.parse(fs.readFileSync(this.configPath, 'utf-8'))
100→
101→    // 4. Apply env var overrides
102→    this.applyEnvOverrides(raw)
103→
104→    // 5. Validate with Zod
105→    const result = ConfigSchema.safeParse(raw)
106→    if (!result.success) {
107→      log.error('Config validation failed')
108→      for (const issue of result.error.issues) {
109→        log.error({ path: issue.path.join('.'), message: issue.message }, 'Validation error')
110→      }
111→      process.exit(1)
112→    }
113→    this.config = result.data
114→  }
115→
116→  get(): Config {
117→    return this.config
118→  }
119→
120→  async save(updates: Record<string, unknown>): Promise<void> {
121→    // Read current file, merge updates, write back
122→    const raw = JSON.parse(fs.readFileSync(this.configPath, 'utf-8'))
123→    this.deepMerge(raw, updates)
124→    fs.writeFileSync(this.configPath, JSON.stringify(raw, null, 2))
125→    // Re-validate and update in-memory config
126→    const result = ConfigSchema.safeParse(raw)
127→    if (result.success) {
128→      this.config = result.data
129→    }
130→  }
131→
132→  resolveWorkspace(input?: string): string {
133→    if (!input) {
134→      const resolved = expandHome(this.config.workspace.baseDir)
135→      fs.mkdirSync(resolved, { recursive: true })
136→      return resolved
137→    }
138→    if (input.startsWith('/') || input.startsWith('~')) {
139→      const resolved = expandHome(input)
140→      fs.mkdirSync(resolved, { recursive: true })
141→      return resolved
142→    }
143→    // Named workspace → lowercase, under baseDir
144→    const name = input.toLowerCase()
145→    const resolved = path.join(expandHome(this.config.workspace.baseDir), name)
146→    fs.mkdirSync(resolved, { recursive: true })
147→    return resolved
148→  }
149→
150→  async exists(): Promise<boolean> {
151→    return fs.existsSync(this.configPath)
152→  }
153→
154→  getConfigPath(): string {
155→    return this.configPath
156→  }
157→
158→  async writeNew(config: Config): Promise<void> {
159→    const dir = path.dirname(this.configPath)
160→    fs.mkdirSync(dir, { recursive: true })
161→    fs.writeFileSync(this.configPath, JSON.stringify(config, null, 2))
162→  }
163→
164→  private applyEnvOverrides(raw: Record<string, unknown>): void {
165→    const overrides: [string, string[]][] = [
166→      ['OPENACP_TELEGRAM_BOT_TOKEN', ['channels', 'telegram', 'botToken']],
167→      ['OPENACP_TELEGRAM_CHAT_ID', ['channels', 'telegram', 'chatId']],
168→      ['OPENACP_DEFAULT_AGENT', ['defaultAgent']],
169→      ['OPENACP_RUN_MODE', ['runMode']],
170→    ]
171→    for (const [envVar, configPath] of overrides) {
172→      const value = process.env[envVar]
173→      if (value !== undefined) {
174→        let target = raw as Record<string, any>
175→        for (let i = 0; i < configPath.length - 1; i++) {
176→          if (!target[configPath[i]]) target[configPath[i]] = {}
177→          target = target[configPath[i]]
178→        }
179→        const key = configPath[configPath.length - 1]
180→        // Convert chatId to number
181→        target[key] = key === 'chatId' ? Number(value) : value
182→      }
183→    }
184→
185→    // Logging env var overrides
186→    if (process.env.OPENACP_LOG_LEVEL) {
187→      raw.logging = raw.logging || {}
188→      ;(raw.logging as Record<string, unknown>).level = process.env.OPENACP_LOG_LEVEL
189→    }
190→    if (process.env.OPENACP_LOG_DIR) {
191→      raw.logging = raw.logging || {}
192→      ;(raw.logging as Record<string, unknown>).logDir = process.env.OPENACP_LOG_DIR
193→    }
194→    if (process.env.OPENACP_DEBUG && !process.env.OPENACP_LOG_LEVEL) {
195→      raw.logging = raw.logging || {}
196→      ;(raw.logging as Record<string, unknown>).level = 'debug'
197→    }
198→  }
199→
200→  private deepMerge(target: Record<string, any>, source: Record<string, any>): void {
201→    for (const key of Object.keys(source)) {
202→      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
203→        if (!target[key]) target[key] = {}
204→        this.deepMerge(target[key], source[key])
205→      } else {
206→        target[key] = source[key]
207→      }
208→    }
209→  }
210→}
