 10→let rootLogger: pino.Logger = pino({
 11→  level: 'debug',
 12→  transport: { target: 'pino-pretty', options: { colorize: true, translateTime: 'SYS:standard' } },
 13→})
 14→let initialized = false
 15→let logDir: string | undefined
 16→
 17→function expandHome(p: string): string {
 18→  return p.startsWith('~') ? path.join(os.homedir(), p.slice(1)) : p
 19→}
 20→
 21→// --- Variadic wrapper for backward compatibility ---
 22→function wrapVariadic(logger: pino.Logger) {
 23→  return {
 24→    info: (...args: unknown[]) => {
 25→      if (args.length === 0) return
 26→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 27→        logger.info(args[0] as object, args.slice(1).join(' '))
 28→      } else {
 29→        logger.info(args.map(String).join(' '))
 30→      }
 31→    },
 32→    warn: (...args: unknown[]) => {
 33→      if (args.length === 0) return
 34→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 35→        logger.warn(args[0] as object, args.slice(1).join(' '))
 36→      } else {
 37→        logger.warn(args.map(String).join(' '))
 38→      }
 39→    },
 40→    error: (...args: unknown[]) => {
 41→      if (args.length === 0) return
 42→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 43→        logger.error(args[0] as object, args.slice(1).join(' '))
 44→      } else {
 45→        logger.error(args.map(String).join(' '))
 46→      }
 47→    },
 48→    debug: (...args: unknown[]) => {
 49→      if (args.length === 0) return
 50→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 51→        logger.debug(args[0] as object, args.slice(1).join(' '))
 52→      } else {
 53→        logger.debug(args.map(String).join(' '))
 54→      }
 55→    },
 56→    fatal: (...args: unknown[]) => {
 57→      if (args.length === 0) return
 58→      if (typeof args[0] === 'object' && args[0] !== null && !(args[0] instanceof Error)) {
 59→        logger.fatal(args[0] as object, args.slice(1).join(' '))
 60→      } else {
 61→        logger.fatal(args.map(String).join(' '))
 62→      }
 63→    },
 64→    child: (bindings: pino.Bindings) => logger.child(bindings),
 65→  }
 66→}
 67→
 68→export const log = wrapVariadic(rootLogger)
 69→
 70→// --- Public API ---
 71→
 72→export function initLogger(config: LoggingConfig): Logger {
 73→  if (initialized) return rootLogger
 74→
 75→  const resolvedLogDir = expandHome(config.logDir)
 76→  logDir = resolvedLogDir
 77→
 78→  try {
 79→    fs.mkdirSync(resolvedLogDir, { recursive: true })
 80→    fs.mkdirSync(path.join(resolvedLogDir, 'sessions'), { recursive: true })
 81→  } catch (err) {
 82→    console.error(`[WARN] Failed to create log directory ${resolvedLogDir}, falling back to console-only:`, err)
 83→    return rootLogger
 84→  }
 85→
 86→  const transports = pino.transport({
 87→    targets: [
 88→      {
 89→        target: 'pino-pretty',
 90→        options: { colorize: true, translateTime: 'SYS:standard' },
 91→        level: config.level,
 92→      },
 93→      {
 94→        target: 'pino-roll',
 95→        options: {
 96→          file: path.join(resolvedLogDir, 'openacp.log'),
 97→          size: config.maxFileSize,
 98→          limit: { count: config.maxFiles },
 99→        },
100→        level: config.level,
101→      },
102→    ],
103→  })
104→
105→  rootLogger = pino({ level: config.level }, transports)
106→  initialized = true
107→
108→  // Update the default log wrapper to use the new root logger
109→  Object.assign(log, wrapVariadic(rootLogger))
110→
111→  return rootLogger
112→}
113→
114→export function createChildLogger(context: { module: string; [key: string]: unknown }): Logger {
115→  // Return a proxy that always delegates to the current rootLogger.
116→  // This ensures child loggers created at module-level (before initLogger)
117→  // pick up the initialized logger with pino-pretty transport.
118→  return new Proxy({} as Logger, {
119→    get(_target, prop, receiver) {
120→      const child = rootLogger.child(context)
121→      const value = Reflect.get(child, prop, receiver)
122→      return typeof value === 'function' ? value.bind(child) : value
123→    },
124→  })
125→}
126→
127→export function createSessionLogger(sessionId: string, parentLogger: Logger): Logger {
128→  const sessionLogDir = logDir ? path.join(logDir, 'sessions') : undefined
129→  if (!sessionLogDir) {
130→    return parentLogger.child({ sessionId })
131→  }
132→
133→  try {
134→    const sessionLogPath = path.join(sessionLogDir, `${sessionId}.log`)
135→    const dest = pino.destination(sessionLogPath)
136→    const sessionFileLogger = pino({ level: parentLogger.level }, dest).child({ sessionId })
137→
138→    // Create a logger that writes to both parent (combined) and session file
139→    const combinedChild = parentLogger.child({ sessionId })
140→    const originalInfo = combinedChild.info.bind(combinedChild)
141→    const originalWarn = combinedChild.warn.bind(combinedChild)
142→    const originalError = combinedChild.error.bind(combinedChild)
143→    const originalDebug = combinedChild.debug.bind(combinedChild)
144→    const originalFatal = combinedChild.fatal.bind(combinedChild)
145→
146→    // Proxy log methods to write to both destinations
147→    combinedChild.info = ((objOrMsg: any, ...rest: any[]) => {
148→      sessionFileLogger.info(objOrMsg, ...rest)
149→      return originalInfo(objOrMsg, ...rest)
150→    }) as any
151→    combinedChild.warn = ((objOrMsg: any, ...rest: any[]) => {
152→      sessionFileLogger.warn(objOrMsg, ...rest)
153→      return originalWarn(objOrMsg, ...rest)
154→    }) as any
155→    combinedChild.error = ((objOrMsg: any, ...rest: any[]) => {
156→      sessionFileLogger.error(objOrMsg, ...rest)
157→      return originalError(objOrMsg, ...rest)
158→    }) as any
159→    combinedChild.debug = ((objOrMsg: any, ...rest: any[]) => {
160→      sessionFileLogger.debug(objOrMsg, ...rest)
161→      return originalDebug(objOrMsg, ...rest)
162→    }) as any
163→    combinedChild.fatal = ((objOrMsg: any, ...rest: any[]) => {
164→      sessionFileLogger.fatal(objOrMsg, ...rest)
165→      return originalFatal(objOrMsg, ...rest)
166→    }) as any
167→
168→    // Store dest for cleanup
169→    ;(combinedChild as any).__sessionDest = dest
170→
171→    return combinedChild
172→  } catch (err) {
173→    // Graceful degradation: session file failed, just use combined log
174→    parentLogger.warn({ sessionId, err }, 'Failed to create session log file, using combined log only')
175→    return parentLogger.child({ sessionId })
176→  }
177→}
178→
179→export async function shutdownLogger(): Promise<void> {
180→  if (!initialized) return
181→
182→  return new Promise<void>((resolve) => {
183→    const timeout = setTimeout(() => {
184→      resolve()
185→    }, 5000)
186→
187→    rootLogger.flush()
188→    // Give transports time to flush
189→    setTimeout(() => {
190→      clearTimeout(timeout)
191→      // Reset to console-only logger so tests can re-init
192→      rootLogger = pino({ level: 'debug' })
193→      Object.assign(log, wrapVariadic(rootLogger))
194→      logDir = undefined
195→      initialized = false
196→      resolve()
197→    }, 500)
198→  })
199→}
200→
201→export async function cleanupOldSessionLogs(retentionDays: number): Promise<void> {
202→  if (!logDir) return
203→
204→  const sessionsDir = path.join(logDir, 'sessions')
205→  try {
206→    const files = await fs.promises.readdir(sessionsDir)
207→    const cutoff = Date.now() - retentionDays * 24 * 60 * 60 * 1000
208→
209→    for (const file of files) {
210→      try {
211→        const filePath = path.join(sessionsDir, file)
212→        const stat = await fs.promises.stat(filePath)
213→        if (stat.mtimeMs < cutoff) {
214→          await fs.promises.unlink(filePath)
215→          rootLogger.debug({ file }, 'Deleted old session log')
216→        }
217→      } catch (err) {
218→        rootLogger.warn({ file, err }, 'Failed to delete old session log')
219→      }
220→    }
221→  } catch {
222→    // Sessions directory doesn't exist — no-op
223→  }
224→}
